function canonical(value){if(value===null||typeof value!=='object')return JSON.stringify(value);if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';return '{'+Object.keys(value).filter(k=>value[k]!==undefined).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';}
function sha(value){return 'sha256:'+createHash('sha256').update(canonical(value)).digest('hex');}
function requireCondition(value,message){if(!value)throw Error(message);}
async function fixture(role,{listDelay=0,archiveDelay=0,phase='prepared'}={}){let teamReads=0,appliedDocs;const expires=Date.now()+60000;const context=await browser.newContext({viewport:{width:1280,height:900}}),page=await context.newPage(),calls=[],errors=[],account=`00000000-0000-4000-8000-00000000000${role==='owner'?1:role==='editor'?2:3}`;await context.tracing.start({screenshots:true,snapshots:true,sources:true});page.on('pageerror',e=>errors.push(e.message));await page.route(`${endpoint}/**`,async route=>{const req=route.request(),u=new URL(req.url()),headers={'Access-Control-Allow-Origin':'*','Content-Type':'application/json'};if(req.method()==='OPTIONS'){await route.fulfill({status:204,headers:{...headers,'Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'*'},body:''});return;}if(u.pathname==='/auth/v1/logout'){calls.push({type:'auth-logout'});await route.fulfill({status:204,headers,body:''});return;}if(u.pathname==='/auth/v1/token'){calls.push({type:'auth-fixture',role});await route.fulfill({headers,body:JSON.stringify({access_token:'independent-fixture-token',user:{id:account},expires_in:3600})});return;}if(u.pathname==='/rest/v1/scenario_snapshots'){calls.push({type:'public-list'});if(listDelay)await new Promise(r=>setTimeout(r,listDelay));await route.fulfill({headers,body:JSON.stringify([{id:shared.id,content_hash:shared.contentHash,created_at:shared.createdAt,expires_at:shared.accessExpiresAt}])});return;}if(u.pathname==='/rest/v1/scenario_comments'){calls.push({type:'comments',method:req.method(),body:req.postData()});await route.fulfill({headers,body:'[]'});return;}if(u.pathname==='/functions/v1/scenario-sync'){const wire=req.postDataJSON();calls.push({type:'edge',action:wire.action,input:wire.input});let data;if(wire.action==='projects')data=role==='owner'?[{projectId:remote.project.projectId,name:remote.project.name,serverRevision:'1',role:'owner'}]:role==='editor'?[{projectId:editorImage.projectId,name:null,serverRevision:'1',role:'editor'}]:[];else if(wire.action==='shared_snapshot')data=shared;else if(wire.action==='team_read'){data={...structuredClone(editorImage),authorizationRevision:'1',authorizationExpiresAt:teamReads++?null:new Date(expires).toISOString()};if(teamReads>1){data.serverRevision='2';data.documents=structuredClone(appliedDocs).filter(d=>d.id===editorImage.documents[0].id);data.contentHash=sha(data.documents);}}else if(wire.action==='pull')data=remote;else if(wire.action==='apply'){const op=wire.input;appliedDocs=structuredClone(editorImage.documents);const target=op.targets[0],doc=appliedDocs.find(d=>d.id===target.targetId);doc.fields.name=target.changes.find(c=>c.field==='name').value.value;doc.revision='2';data={schemaVersion:1,operationId:op.operationId,scope:op.scope,operationHash:sha(op),status:'applied',serverRevision:'2',authorizationRevision:'1',authorizationExpiresAt:new Date(expires).toISOString(),documents:[doc],confirmedDocuments:appliedDocs,conflicts:[]};}else if(wire.action==='download_archive'){if(archiveDelay)await new Promise(r=>setTimeout(r,archiveDelay));await route.fulfill({status:200,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/octet-stream','Content-Length':String(archive.length)},body:archive});return;}else{await route.fulfill({status:500,headers,body:JSON.stringify({code:'UNEXPECTED_FIXTURE_ACTION',action:wire.action})});return;}await route.fulfill({headers,body:JSON.stringify(data)});return;}await route.fulfill({status:404,headers,body:'{}'});});return {context,page,calls,errors,account,expires};}
async function login(f,query=''){await f.page.goto(url+query);await f.page.getByRole('button',{name:'アカウント・専用同期',exact:true}).click();await f.page.getByLabel('専用Supabase URL',{exact:true}).fill(endpoint+'/');await f.page.getByLabel('公開用APIキー',{exact:true}).fill('sb_publishable_independent_fixture_only');await f.page.getByRole('button',{name:'接続設定を保持',exact:true}).click();await f.page.getByLabel('メール',{exact:true}).fill('independent@example.invalid');await f.page.getByLabel('パスワード',{exact:true}).fill('fixture-not-real-password');await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).click();await f.page.getByRole('button',{name:'限定版の閲覧・指摘',exact:true}).waitFor();await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).waitFor({state:'visible'});}
